import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import hashlib

app = Flask(__name__)
UPLOAD_DIR = '/tmp/reports'
TEMPLATE_DIR = '/opt/app/templates'

os.makedirs(UPLOAD_DIR, exist_ok=True)

def get_template_path(template_name):
    """Resolve template path - supports subdirectories for org-specific templates"""
    # Basic sanitization - remove null bytes and normalize
    cleaned = template_name.replace('\x00', '').strip()
    # Allow alphanumeric, dots, hyphens, underscores, and forward slashes for subdirs
    if not all(c.isalnum() or c in '.-_/' for c in cleaned):
        return None
    path = os.path.join(TEMPLATE_DIR, cleaned)
    return path

@app.route('/api/v1/reports/generate', methods=['POST'])
def generate_report():
    """Generate PDF report from template with user-supplied variables"""
    data = request.get_json()
    if not data:
        return jsonify({'error': 'JSON body required'}), 400

    template_name = data.get('template', 'default.tex')
    variables = data.get('variables', {})
    output_format = data.get('format', 'pdf')

    template_path = get_template_path(template_name)
    if template_path is None:
        return jsonify({'error': 'Invalid template name'}), 400

    if not os.path.isfile(template_path):
        return jsonify({'error': 'Template not found'}), 404

    try:
        with open(template_path, 'r') as f:
            content = f.read()
    except IOError:
        return jsonify({'error': 'Cannot read template'}), 500

    # Substitute variables into template
    for key, value in variables.items():
        placeholder = '{{' + key + '}}'
        # Escape LaTeX special chars in values
        safe_value = str(value).replace('\\', '\\textbackslash{}')
        for ch in '&%$#_{}~^':
            safe_value = safe_value.replace(ch, '\\' + ch)
        content = content.replace(placeholder, safe_value)

    # Write populated template to temp file
    job_id = hashlib.sha256(os.urandom(16)).hexdigest()[:12]
    work_dir = os.path.join(UPLOAD_DIR, job_id)
    os.makedirs(work_dir, exist_ok=True)

    tex_path = os.path.join(work_dir, 'report.tex')
    with open(tex_path, 'w') as f:
        f.write(content)

    # Compile LaTeX to PDF
    cmd = f'cd {work_dir} && pdflatex -interaction=nonstopmode report.tex'
    result = subprocess.run(cmd, shell=True, capture_output=True, timeout=30)

    pdf_path = os.path.join(work_dir, 'report.pdf')
    if not os.path.isfile(pdf_path):
        return jsonify({'error': 'Compilation failed', 'log': result.stderr.decode()[-500:]}), 500

    return send_file(pdf_path, mimetype='application/pdf', as_attachment=True,
                     download_name=f'report-{job_id}.pdf')

@app.route('/api/v1/reports/templates', methods=['GET'])
def list_templates():
    """List available templates"""
    templates = []
    for root, dirs, files in os.walk(TEMPLATE_DIR):
        for f in files:
            if f.endswith('.tex'):
                rel = os.path.relpath(os.path.join(root, f), TEMPLATE_DIR)
                templates.append(rel)
    return jsonify({'templates': templates})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
